:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-lilac-mist: #faf8ff;
  --color-lavender-tile: #ece9ff;
  --color-frosted-tile: #e3f2f8;
  --color-plum-night: #231850;
  --color-plum-basement: #191034;
  --color-plum-ink: #281950;
  --color-slate-body: #5b4f78;
  --color-pewter-label: #6d5f8f;
  --color-heather-caption: #a39ac1;
  --color-lilac-hairline: #e4def7;
  --color-violet-ink: #6d28d9;
  --color-ember-signal: #f86d60;

  /* Typography — Font Families */
  --font-mackinac: "Mackinac", "Fraunces", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-fricolage-grotesque: "Fricolage Grotesque", "Bricolage Grotesque", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.5;
  --tracking-small: 0.96px;
  --text-caption: 14.5px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 17px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 19px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 23px;
  --leading-subheading: 1.35;
  --tracking-subheading: -0.575px;
  --text-heading-sm: 26px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: -0.65px;
  --text-heading: 32px;
  --leading-heading: 1.25;
  --tracking-heading: -0.8px;
  --text-heading-lg: 44px;
  --leading-heading-lg: 1.08;
  --tracking-heading-lg: -1.1px;
  --text-display: 56px;
  --leading-display: 1.15;
  --tracking-display: -1.68px;

  /* Typography — Weights */
  --font-weight-light: 325;
  --font-weight-light-2: 350;
  --font-weight-regular: 450;
  --font-weight-medium: 500;
  --font-weight-semibold: 575;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1200px;
  --layout-section-gap: 96px;
  --layout-card-padding: 32px;
  --layout-element-gap: 16px;
  --layout-nav-height: 96px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-xl: 16px;
  --radius-2xl: 20px;
  --radius-3xl: 24px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 24px;
  --radius-small-cards: 16px;
  --radius-inner-tiles: 10px;
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-nav: 9999px;
  --radius-inputs: 8px;
  --radius-small-elements: 6px;
  --radius-images: 0px;

  /* Shadows */
  --shadow-subtle: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-subtle-2: inset 0 -3px 6px -2px rgba(231, 230, 244, 1);
  --shadow-sm: 0 5px 5px -2px rgba(91, 33, 182, 0.1), 0 2px 4px -2px rgba(91, 33, 182, 0.1);
  --shadow-sm-2: inset 0 0 0 1.5px rgba(252, 185, 178, 1);
  --shadow-md: 0 1px 2px 0 rgba(40, 25, 80, 0.04), 0 16px 40px -20px rgba(40, 25, 80, 0.14);
  --shadow-lg: 0 0 0 1px rgba(32, 34, 55, 0.075), 0 10px 15px -3px rgba(32, 34, 55, 0.05), 0 4px 6px -4px rgba(32, 34, 55, 0.05);
  --shadow-xl: 0 24px 60px 0 rgba(40, 25, 80, 0.14);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-lilac-mist: #faf8ff;
  --surface-lavender-tile: #ece9ff;
  --surface-plum-night: #231850;
  --surface-plum-basement: #191034;
}

